<script>
 import {onMount,onDestroy} from 'svelte';
 import {formatDate} from '$lib/date.js';
 import {locale} from '$lib/i18n.js';
 import {notify} from '$lib/stores.js';
 import Button from '$lib/components/Button.svelte';
 let logs=[],summary={total:0,errors:0,warnings:0},loading=true,error='',search='',level='all',category='all',limit=200,autoRefresh=true,refreshTimer=null,selected=null;
 $: ru=$locale!=='en';
 $: filtered=logs.filter(x=>{const q=search.trim().toLowerCase();return (!q||JSON.stringify(x).toLowerCase().includes(q))&&(level==='all'||x.level===level)&&(category==='all'||x.category===category)});
 async function load(silent=false){
  if(!silent)loading=true;error='';
  const q=new URLSearchParams({limit:String(limit)});if(level!=='all')q.set('level',level);if(category!=='all')q.set('category',category);if(search.trim())q.set('q',search.trim());
  try{const response=await fetch('/api/system-logs?'+q.toString(),{credentials:'same-origin',headers:{Accept:'application/json'}});const body=await response.json().catch(()=>({}));if(!response.ok){throw new Error(body.error||('HTTP '+response.status))}logs=body.logs||[];summary=body.summary||summary;}
  catch(e){error=e?.message||'Failed to load system logs';if(!silent)notify(error,'error')}
  finally{loading=false}
 }
 function scheduleRefresh(){if(refreshTimer)clearInterval(refreshTimer);refreshTimer=autoRefresh?setInterval(()=>load(true),10000):null}
 onMount(()=>{load();scheduleRefresh()});onDestroy(()=>{if(refreshTimer)clearInterval(refreshTimer)});
 $: if(typeof autoRefresh!=='undefined') scheduleRefresh();
 function exportCSV(){const rows=[['timestamp','level','category','source','message','request_id','method','path','status','duration_ms'],...filtered.map(x=>[x.created_at,x.level,x.category,x.source,x.message,x.request_id,x.method,x.path,x.status_code,x.duration_ms])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='yevqo-system-logs.csv';a.click();URL.revokeObjectURL(url)}
 async function copy(value){try{await navigator.clipboard.writeText(String(value||''));notify(ru?'Скопировано':'Copied','success')}catch{notify(ru?'Не удалось скопировать':'Copy failed','error')}}
 function levelLabel(v){return ({debug:'DEBUG',info:'INFO',warn:'WARN',error:'ERROR'})[v]||v}
</script>
<svelte:head><title>{ru?'Системные журналы':'System logs'} · Yevqo</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">ADMINISTRATION / OBSERVABILITY</div><h1 class="page-title">{ru?'Системные журналы':'System logs'}</h1><p class="page-desc">{ru?'Внутренние события Control Plane, HTTP-запросы и диагностика служб.':'Control Plane events, HTTP requests and service diagnostics.'}</p></div><div class="actions"><label class="auto"><input type="checkbox" bind:checked={autoRefresh}/>{ru?'Автообновление · 10 с':'Auto refresh · 10s'}</label><Button on:click={()=>load()} disabled={loading}>↻ {ru?'Обновить':'Refresh'}</Button><Button variant="primary" on:click={exportCSV} disabled={!filtered.length}>{ru?'Экспорт CSV':'Export CSV'}</Button></div></div>
<div class="stats"><article><small>{ru?'ЗАПИСЕЙ В ВЫБОРКЕ':'MATCHING EVENTS'}</small><strong>{summary.total.toLocaleString()}</strong><span>{ru?'Всего по фильтру':'Total for current filters'}</span></article><article><small>ERROR</small><strong class:danger={summary.errors>0}>{summary.errors.toLocaleString()}</strong><span>{ru?'Ошибок в журнале':'Errors in journal'}</span></article><article><small>WARN</small><strong class:warning={summary.warnings>0}>{summary.warnings.toLocaleString()}</strong><span>{ru?'Предупреждений':'Warnings'}</span></article><article><small>{ru?'ПОКАЗАНО':'DISPLAYED'}</small><strong>{filtered.length}</strong><span>{ru?'Последние записи':'Latest records'}</span></article></div>
<div class="toolbar"><input class="search" bind:value={search} on:keydown={(e)=>e.key==='Enter'&&load()} placeholder={ru?'Поиск по сообщению, пути, request ID…':'Search message, path, request ID…'}/><select bind:value={level}><option value="all">{ru?'Все уровни':'All levels'}</option><option value="debug">DEBUG</option><option value="info">INFO</option><option value="warn">WARN</option><option value="error">ERROR</option></select><select bind:value={category}><option value="all">{ru?'Все категории':'All categories'}</option>{#each ['system','http','authentication','cloudflare','github','integrations','projects','devices','agent','command','builds','deployments','admin','backups','database'] as c}<option value={c}>{c}</option>{/each}</select><select bind:value={limit} on:change={()=>load()}><option value="50">50</option><option value="100">100</option><option value="200">200</option><option value="500">500</option></select><Button on:click={()=>{search='';level='all';category='all';load()}}>{ru?'Сбросить':'Reset'}</Button></div>
{#if error}<div class="error" role="alert"><strong>{ru?'Не удалось загрузить системные журналы':'Could not load system logs'}</strong><p>{error}</p><Button on:click={()=>load()}>{ru?'Повторить':'Retry'}</Button></div>{/if}
{#if loading}<div class="empty">{ru?'Загрузка…':'Loading…'}</div>{:else if !filtered.length}<div class="empty">{ru?'Нет системных событий по выбранным фильтрам.':'No system events match these filters.'}</div>{:else}
<div class="table"><div class="head"><span>{ru?'Время':'Timestamp'}</span><span>{ru?'Уровень':'Level'}</span><span>{ru?'Категория':'Category'}</span><span>{ru?'Источник':'Source'}</span><span>{ru?'Событие':'Event'}</span><span>HTTP</span></div>{#each filtered as item (item.id)}<button class="entry" on:click={()=>selected=item}><time>{formatDate(item.created_at)}</time><span class={'level '+item.level}>{levelLabel(item.level)}</span><span class="category">{item.category}</span><span>{item.source}</span><strong>{item.message}</strong><span class="http">{item.status_code||'—'}{#if item.duration_ms} · {item.duration_ms}ms{/if}</span></button>{/each}</div>
{/if}
<div class="foot"><span>{ru?'Показываются последние':'Showing latest'} {logs.length} {ru?'записей':'records'} · {ru?'Хранение — в базе Control Plane':'Stored in Control Plane database'}</span><span>{autoRefresh?(ru?'Автообновление включено':'Auto refresh on'):(ru?'Автообновление выключено':'Auto refresh off')}</span></div>
{#if selected}<div class="backdrop" on:click={()=>selected=null}><section class="drawer" on:click|stopPropagation><header><div><h2>{ru?'Событие журнала':'Log event'}</h2><small>#{selected.id} · {selected.request_id||'no request id'}</small></div><button on:click={()=>selected=null}>×</button></header><div class="detail"><span>{ru?'Время':'Timestamp'}</span><strong>{formatDate(selected.created_at)}</strong></div><div class="detail"><span>{ru?'Уровень':'Level'}</span><strong class={'level '+selected.level}>{levelLabel(selected.level)}</strong></div><div class="detail"><span>{ru?'Категория':'Category'}</span><strong>{selected.category}</strong></div><div class="detail"><span>{ru?'Источник':'Source'}</span><strong>{selected.source}</strong></div><div class="detail"><span>{ru?'Пользователь':'User ID'}</span><strong>{selected.user_id||'—'}</strong></div><div class="detail"><span>{ru?'Устройство':'Device ID'}</span><strong>{selected.device_id||'—'}</strong></div><div class="detail"><span>HTTP</span><strong>{selected.method||'—'} {selected.path||''} · {selected.status_code||'—'} · {selected.duration_ms||0}ms</strong></div><h3>{selected.message}</h3><pre>{JSON.stringify(selected.metadata||{},null,2)}</pre><div class="drawer-actions"><Button on:click={()=>copy(selected.request_id)}>{ru?'Копировать Request ID':'Copy Request ID'}</Button><Button on:click={()=>copy(JSON.stringify(selected,null,2))}>{ru?'Копировать событие':'Copy event'}</Button></div></section></div>{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:var(--accent);font-weight:700;margin-bottom:7px}.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.auto{display:flex;align-items:center;gap:6px;color:var(--text-muted);font-size:10px}.auto input{accent-color:var(--accent)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.stats article{padding:14px;background:var(--bg-card);border:1px solid var(--border);border-radius:9px}.stats small,.stats span{display:block;color:var(--text-muted);font-size:9px}.stats small{letter-spacing:.1em}.stats strong{display:block;font-size:21px;margin:7px 0 3px}.stats strong.danger{color:var(--danger)}.stats strong.warning{color:var(--warning)}.toolbar{display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap}.toolbar .search{flex:1;min-width:220px}.toolbar input,.toolbar select{background:var(--bg-card);border:1px solid var(--border);border-radius:7px;padding:9px 10px;color:var(--text-main);font-size:10px}.toolbar select{min-width:110px}.table{border:1px solid var(--border);border-radius:9px;overflow:hidden;background:var(--bg-card)}.head,.entry{display:grid;grid-template-columns:1.15fr .55fr .8fr .8fr 1.7fr .8fr;gap:10px;align-items:center;padding:10px 12px}.head{background:var(--bg-elevated);color:var(--text-muted);font-size:9px;text-transform:uppercase;letter-spacing:.07em}.entry{width:100%;text-align:left;background:transparent;color:var(--text-main);border:0;border-top:1px solid var(--border);font-size:10px}.entry:hover{background:var(--bg-hover)}.entry time,.entry>span{font-size:9px;color:var(--text-muted);overflow-wrap:anywhere}.entry strong{font-weight:500;overflow-wrap:anywhere}.level{font-size:9px;font-weight:700;letter-spacing:.04em}.level.error{color:var(--danger)}.level.warn{color:var(--warning)}.level.info{color:var(--accent)}.level.debug{color:var(--text-muted)}.category{color:var(--accent)!important}.http{font-variant-numeric:tabular-nums}.foot{display:flex;justify-content:space-between;gap:10px;color:var(--text-muted);font-size:9px;margin-top:12px}.empty{padding:35px;text-align:center;color:var(--text-muted);font-size:11px}.error{padding:14px;margin-bottom:12px;border:1px solid var(--danger);border-radius:8px;background:var(--bg-card);font-size:11px}.error p{color:var(--text-muted);overflow-wrap:anywhere}.backdrop{position:fixed;inset:0;z-index:80;background:#0009;display:flex;justify-content:flex-end}.drawer{width:min(480px,100%);height:100%;overflow:auto;background:var(--bg-card);border-left:1px solid var(--border);padding:20px}.drawer header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.drawer h2{font-size:15px;margin:0 0 5px}.drawer header small{font-size:9px;color:var(--text-muted)}.drawer header button{border:0;background:none;color:var(--text-main);font-size:22px}.detail{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--border);font-size:10px}.detail span{color:var(--text-muted)}.detail strong{text-align:right;overflow-wrap:anywhere}.drawer h3{font-size:12px;line-height:1.5;margin:18px 0}.drawer pre{background:var(--bg-base);border:1px solid var(--border);border-radius:7px;padding:12px;white-space:pre-wrap;overflow-wrap:anywhere;font:10px var(--mono)}.drawer-actions{display:flex;gap:8px;flex-wrap:wrap}.error{color:var(--danger)}
@media(max-width:850px){.stats{grid-template-columns:repeat(2,1fr)}.head{display:none}.entry{grid-template-columns:1fr 1fr;gap:5px}.entry strong{grid-column:1/-1}.entry time{grid-column:1/-1}.entry>span:last-child{justify-self:end}.toolbar .search{flex-basis:100%}.toolbar select{flex:1;min-width:0}.foot{flex-direction:column}.actions{justify-content:flex-start}}
</style>
